import{_ as d,o,c as t,a1 as c}from"./chunks/framework.BKrM4vFX.js";const m=JSON.parse('{"title":"alfa-mock — мок интернет-эквайринга Альфа-Банка (REST *.do)","description":"alfa-mock — мок интернет-эквайринга Альфа-Банка (REST *.do). © 2026 ООО «Аксиома» ИНН:7842223709 · mock-services · Apache-2.0 SPDX-License-Identifier: Apache-2.0 Второй внешний банк-адаптер стенда (issue #41, Stage 2): мок воспроизводит REST-интерфейс шлюза Альфа-Банка (платформа ","frontmatter":{"sourcePath":"services/alfa-mock/README.md"},"headers":[{"level":1,"title":"alfa-mock — мок интернет-эквайринга Альфа-Банка (REST *.do)","slug":"alfa-mock-мок-интернет-эквайринга-Альфа-Банка-rest-do","link":"#alfa-mock-мок-интернет-эквайринга-Альфа-Банка-rest-do","children":[{"level":2,"title":"Зачем","slug":"Зачем","link":"#Зачем","children":[]},{"level":2,"title":"Запуск","slug":"Запуск","link":"#Запуск","children":[]},{"level":2,"title":"API","slug":"api","link":"#api","children":[]},{"level":2,"title":"Креды — синтетические, не банковские","slug":"Креды-синтетические-не-банковские","link":"#Креды-синтетические-не-банковские","children":[]},{"level":2,"title":"Состояния заказа (orderStatus)","slug":"Состояния-заказа-orderstatus","link":"#Состояния-заказа-orderstatus","children":[]},{"level":2,"title":"Ошибки (формат шлюза + DX)","slug":"Ошибки-формат-шлюза-dx","link":"#Ошибки-формат-шлюза-dx","children":[]},{"level":2,"title":"Callback: HTTP GET + checksum HMAC-SHA256","slug":"callback-http-get-checksum-hmac-sha256","link":"#callback-http-get-checksum-hmac-sha256","children":[]},{"level":2,"title":"Тестовые карты и ACS","slug":"Тестовые-карты-и-acs","link":"#Тестовые-карты-и-acs","children":[]},{"level":2,"title":"Сценарии (X-Mock-Scenario и /mock/scenarios)","slug":"Сценарии-x-mock-scenario-и-mockscenarios","link":"#Сценарии-x-mock-scenario-и-mockscenarios","children":[]},{"level":2,"title":"Виртуальные часы","slug":"Виртуальные-часы","link":"#Виртуальные-часы","children":[]},{"level":2,"title":"Песочницы (RFC-001)","slug":"Песочницы-rfc-001","link":"#Песочницы-rfc-001","children":[]},{"level":2,"title":"Переменные окружения","slug":"Переменные-окружения","link":"#Переменные-окружения","children":[]},{"level":2,"title":"Отличия от tbank-mock и yookassa-mock — не drop-in","slug":"Отличия-от-tbank-mock-и-yookassa-mock-не-drop-in","link":"#Отличия-от-tbank-mock-и-yookassa-mock-не-drop-in","children":[]},{"level":2,"title":"Границы и документированные форки","slug":"Границы-и-документированные-форки","link":"#Границы-и-документированные-форки","children":[]},{"level":2,"title":"Контракты стенда не менялись","slug":"Контракты-стенда-не-менялись","link":"#Контракты-стенда-не-менялись","children":[]},{"level":2,"title":"Байтовые квоты состояния (PD-02)","slug":"Байтовые-квоты-состояния-pd-02","link":"#Байтовые-квоты-состояния-pd-02","children":[]}]}],"relativePath":"services/alfa-mock/README.md","filePath":"services/alfa-mock/README.md"}'),a={name:"services/alfa-mock/README.md"};function r(s,e,i,l,n,h){return o(),t("div",null,[...e[0]||(e[0]=[c('<p>© 2026 ООО «Аксиома» ИНН:7842223709 · mock-services · Apache-2.0 SPDX-License-Identifier: Apache-2.0</p><h1 id="alfa-mock-мок-интернет-эквайринга-Альфа-Банка-rest-do" tabindex="-1">alfa-mock — мок интернет-эквайринга Альфа-Банка (REST <code>*.do</code>) <a class="header-anchor" href="#alfa-mock-мок-интернет-эквайринга-Альфа-Банка-rest-do" aria-label="Permalink to &quot;alfa-mock — мок интернет-эквайринга Альфа-Банка (REST `*.do`)&quot;">​</a></h1><p>Второй <strong>внешний банк-адаптер</strong> стенда (issue #41, Stage 2): мок воспроизводит REST-интерфейс шлюза Альфа-Банка (платформа RBS) — <code>https://alfa.rbsuat.com/payment/rest</code> (тестовый контур) — по публичной документации: регистрация заказа form-параметрами, платёжная страница <code>formUrl</code> с тестовыми картами и ACS (3DS1/3DS2), статусы <code>getOrderStatus(Extended).do</code>, двухстадийная схема (<code>registerPreAuth</code> → <code>deposit</code>), <code>reverse</code>, полный/частичный <code>refund</code> и callback-уведомления <strong>HTTP GET</strong> с симметричным checksum <strong>HMAC-SHA256</strong>. Источник — официальная документация Альфа-Банк (<a href="https://alfabank.ru/sme/payservice/internet-acquiring/docs/connection-options/api/rest/" target="_blank" rel="noreferrer">REST-интерфейс</a>); интеграционный гайд — <a href="./../../docs/integration/alfa"><code>docs/integration/alfa.md</code></a>.</p><h2 id="Зачем" tabindex="-1">Зачем <a class="header-anchor" href="#Зачем" aria-label="Permalink to &quot;Зачем&quot;">​</a></h2><ul><li>прогнать интеграцию с Альфа-Банком от <code>register.do</code> до callback и сверки статуса, не подключаясь к банку (тестовые креды банк выдаёт индивидуально);</li><li>отработать ловушки контракта: <code>errorCode=0</code> ≠ факт оплаты, уникальный <code>orderNumber</code> (повтор — ошибка, не replay), суммы в копейках, ACK callback ровно HTTP 200, неподписанные уведомления (сверка через REST), <code>sessionTimeoutSecs</code> → <code>declinedByTimeout</code>;</li><li>проверить негативные ветки: неверные креды, <code>deposit</code> больше холда, <code>refund</code> больше списанного, операции не в том статусе, отказы карт (-2011, 116, 71015) и сетевые сбои (500/504/latency/hang).</li></ul><h2 id="Запуск" tabindex="-1">Запуск <a class="header-anchor" href="#Запуск" aria-label="Permalink to &quot;Запуск&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start:alfa</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # http://localhost:3104</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># или в общем стенде:</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # alfa-mock на :3104</span></span></code></pre></div><p>Zero npm dependencies, Node ≥ 18. Стартовый лог печатает <strong>синтетические дефолты</strong> кредов (если значение задано через env — <code>&lt;задан через env, скрыт&gt;</code>, фактическое значение не печатается), режим checksum, флаги двухстадийной схемы и ретраев.</p><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Маршрут</th><th>Назначение</th></tr></thead><tbody><tr><td><code>POST /payment/rest/register.do</code></td><td>регистрация заказа (одностадийная оплата) → <code>{orderId, formUrl}</code></td></tr><tr><td><code>POST /payment/rest/registerPreAuth.do</code></td><td>регистрация с холдом (двухстадийная схема)</td></tr><tr><td><code>POST /payment/rest/deposit.do</code></td><td>завершение холда, сумма ≤ авторизованной</td></tr><tr><td><code>POST /payment/rest/reverse.do</code></td><td>отмена холда/оплаты до окончательного расчёта</td></tr><tr><td><code>POST /payment/rest/refund.do</code></td><td>полный/частичный возврат списанного</td></tr><tr><td><code>POST /payment/rest/getOrderStatus.do</code></td><td>статус заказа (серверная сверка)</td></tr><tr><td><code>POST /payment/rest/getOrderStatusExtended.do</code></td><td>расширенный статус: суммы авторизации/списания/возврата, код шлюза</td></tr><tr><td><code>GET /payment/{orderId}</code></td><td>платёжная страница (<code>formUrl</code>): тестовые карты, ACS</td></tr><tr><td><code>POST /payment/{orderId}/pay</code>, <code>/3ds</code></td><td>отправка данных карты и пароля ACS (эмуляция формы)</td></tr><tr><td><code>GET /health</code>, <code>GET /openapi.json</code></td><td>живость/счётчики и спецификация OpenAPI 3.1</td></tr><tr><td><code>GET /admin</code>, <code>GET /admin/journal</code></td><td>консоль (заказы, callback, журнал с curl)</td></tr><tr><td><code>POST /admin/action</code></td><td>действие консоли (<code>deposit-order</code>, <code>reverse-order</code>, <code>expire-order</code>, <code>duplicate-callback</code>); same-origin + CSRF <code>_csrf</code> из формы <code>/admin</code>, иначе 403</td></tr><tr><td><code>/mock/time</code>, <code>/mock/scenarios</code>, <code>/mock/state</code>, <code>/mock/reset</code></td><td>виртуальные часы, сценарии, снимок состояния</td></tr><tr><td><code>/sandboxes*</code>, <code>/mock/sandboxes</code></td><td>песочницы RFC-001 (свои креды на арендатора)</td></tr></tbody></table><p>Транспорт: <code>POST</code> c <code>application/x-www-form-urlencoded</code> (креды <code>userName</code> и <code>password</code> — в каждом запросе, токенов нет). Протокольные ошибки отдаются с <strong>HTTP 200</strong> и <code>{errorCode, errorMessage}</code> — как отвечает шлюз; реальные HTTP-коды (404/405/413/500/504) — у инфраструктурных сбоев.</p><h2 id="Креды-синтетические-не-банковские" tabindex="-1">Креды — синтетические, не банковские <a class="header-anchor" href="#Креды-синтетические-не-банковские" aria-label="Permalink to &quot;Креды — синтетические, не банковские&quot;">​</a></h2><p>Дефолты стенда: <code>userName=ALFAMOCKTEST</code>, <code>password=mockpass123</code>, секрет checksum <code>mocksecret123</code>. Они <strong>сконструированы по образцу TBANKMOCKTEST</strong> и не имеют отношения к Альфа-Банку: реальные тестовые реквизиты банк выдаёт индивидуально при подключении, и зашивать их в дефолты конфига нельзя (<code>документации Альфа-Банк</code>). Переопределение — <code>MOCK_ALFA_USERNAME</code>, <code>MOCK_ALFA_PASSWORD</code>, <code>MOCK_ALFA_CALLBACK_SECRET</code>; в owned-песочницах у каждого арендатора свои креды (<code>POST /sandboxes</code>).</p><p>Фактические креды (env или per-sandbox) <strong>не попадают ни в HTTP-ответы, ни в stdout</strong>: hint ошибки <code>errorCode=2</code> называет только синтетические дефолты (PG-01/PG-02).</p><h2 id="Состояния-заказа-orderstatus" tabindex="-1">Состояния заказа (<code>orderStatus</code>) <a class="header-anchor" href="#Состояния-заказа-orderstatus" aria-label="Permalink to &quot;Состояния заказа (`orderStatus`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Код</th><th>Значение</th><th>Как получается в моке</th></tr></thead><tbody><tr><td>0</td><td>зарегистрирован, не оплачен</td><td><code>register.do</code> / <code>registerPreAuth.do</code></td></tr><tr><td>1</td><td>сумма захолдирована</td><td>оплата формы после <code>registerPreAuth.do</code></td></tr><tr><td>2</td><td>оплата проведена</td><td>оплата формы после <code>register.do</code> либо <code>deposit.do</code></td></tr><tr><td>3</td><td>авторизация отменена</td><td><code>reverse.do</code> из 1 или 2</td></tr><tr><td>4</td><td>проведён возврат</td><td><code>refund.do</code> из 2 или 4</td></tr><tr><td>5</td><td>начата аутентификация ACS</td><td>отправка 3DS-карты на форме</td></tr><tr><td>6</td><td>авторизация отклонена</td><td>отказ карты, Fail/неверный пароль ACS, истёк <code>sessionTimeoutSecs</code></td></tr></tbody></table><p><code>actionCode</code> — код ответа шлюза: <code>0</code> одобрено, <code>-2011</code> (3DS PaRes=U), <code>116</code> (недостаточно средств), <code>71015</code> («введённая информация неверна» — неверный срок/CVV либо Fail на ACS), <code>5</code> (общий отказ эмитента: неизвестная валидная карта, операция без 3DS при выключенном SSL-разрешении).</p><h2 id="Ошибки-формат-шлюза-dx" tabindex="-1">Ошибки (формат шлюза + DX) <a class="header-anchor" href="#Ошибки-формат-шлюза-dx" aria-label="Permalink to &quot;Ошибки (формат шлюза + DX)&quot;">​</a></h2><p>Ответ ошибки: <code>{errorCode, errorMessage}</code> плюс DX-поля мока <code>field</code>, <code>hint</code>, <code>doc</code> (не часть протокола). Коды — классическая таблица платформы RBS:</p><table tabindex="0"><thead><tr><th>errorCode</th><th>Смысл</th><th>Типовые причины в моке</th></tr></thead><tbody><tr><td>1</td><td>номер заказа уже зарегистрирован</td><td>повтор <code>orderNumber</code></td></tr><tr><td>2</td><td>merchant-логин не найден / неверный пароль</td><td>чужие креды (в owned-песочнице — креды другой песочницы)</td></tr><tr><td>3</td><td>номер заказа некорректен</td><td>нет/длиннее 64 символов <code>orderNumber</code>, неизвестный <code>orderId</code>/<code>orderNumber</code></td></tr><tr><td>4</td><td>состояние заказа некорректно</td><td><code>deposit</code> не по холду, <code>refund</code> до списания, повторный <code>reverse</code></td></tr><tr><td>5</td><td>операция отклонена</td><td>дробный/отрицательный <code>amount</code>, <code>deposit</code> &gt; холда, <code>refund</code> &gt; списанного, битый <code>returnUrl</code>/<code>jsonParams</code>, валюта ≠ 643, двухстадийная схема выключена</td></tr><tr><td>6</td><td>системная ошибка</td><td>сценарий <code>fail</code>, неизвестный REST-метод, инфраструктурные сбои (с честными HTTP 404/405/413/500/504)</td></tr></tbody></table><h2 id="callback-http-get-checksum-hmac-sha256" tabindex="-1">Callback: HTTP GET + checksum HMAC-SHA256 <a class="header-anchor" href="#callback-http-get-checksum-hmac-sha256" aria-label="Permalink to &quot;Callback: HTTP GET + checksum HMAC-SHA256&quot;">​</a></h2><p>Уведомление доставляется <strong>GET-запросом с query-параметрами</strong>: <code>mdOrder</code> (= <code>orderId</code>), <code>orderNumber</code>, <code>operation</code>, <code>status</code> (<code>1</code> успех / <code>0</code> ошибка), <code>amount</code> (копейки), <code>callbackCreationDate</code> (epoch-мс) и <code>checksum</code>. Операции: <code>approved</code> (холд), <code>deposited</code> (списание), <code>reversed</code> (отмена), <code>refunded</code> (возврат), <code>declinedByTimeout</code> (истёк срок оплаты), <code>declinedCardpresent</code> (отказ карточной авторизации — см. «Границы и форки»).</p><ul><li><strong>ACK — ровно HTTP 200</strong>: любой иной код (включая 204) считается неуспехом, доставка повторяется. Число попыток и интервал официальный PDF <strong>не задаёт</strong> — <code>MOCK_CALLBACK_RETRY_MS</code> × <code>MOCK_CALLBACK_MAX_ATTEMPTS</code> это mock-конфиг, а не параметры банка.</li><li><strong>Checksum (симметричный режим)</strong>: удалить <code>checksum</code> и <code>sign_alias</code>, отсортировать имена параметров в алфавитном порядке, построить строку <code>name;value;name;value;…;</code>, HMAC-SHA256 с общим секретом, hex <strong>в верхнем регистре</strong>. Пример проверки — в <a href="./../../docs/integration/alfa"><code>docs/integration/alfa.md</code></a>.</li><li><strong>Callback без checksum возможен</strong> (<code>MOCK_CALLBACK_CHECKSUM=false</code> эмулирует этот режим): неподписанное уведомление можно подделать — приёмник обязан сверять статус через <code>getOrderStatusExtended.do</code>, а не менять состояние заказа по одному факту уведомления.</li><li><strong>Асимметричный режим НЕ реализован</strong>: официальное описание говорит о SHA-256, а примеры кода (Java <code>SHA512withRSA</code>, PHP <code>OPENSSL_ALGO_SHA512</code>) — о SHA-512; режим подтверждается банком по merchant-аккаунту. Домысливать алгоритм нельзя — вне области #41.</li><li>Адрес приёмника: в бою задаётся в настройках мерчанта банком; у мока — <code>jsonParams.callback_url</code> (mock-расширение) или <code>MOCK_DEFAULT_CALLBACK_URL</code>. Без адреса уведомления не уходят — сверка через REST.</li></ul><h2 id="Тестовые-карты-и-acs" tabindex="-1">Тестовые карты и ACS <a class="header-anchor" href="#Тестовые-карты-и-acs" aria-label="Permalink to &quot;Тестовые карты и ACS&quot;">​</a></h2><p>Платёжная страница содержит пресеты карт из официального списка (<code>документации Альфа-Банк</code>): успех — <code>4111111111111111</code> (3DS1), <code>639002000000000003</code> (МИР, 18 цифр), <code>2201382000000062</code> (3DS2 frictionless), <code>2200000000000053</code> и <code>2201382000000021/13/39/47/54</code> (3DS2 challenge); отказы — <code>5555555555555557</code>, <code>4444333322221111</code>, <code>5555555544444442</code> (PaRes=U, <code>-2011</code>), <code>5432543254325430</code> (CVV <code>521</code>, недостаточно средств, <code>116</code>), <code>5555555555555599</code> (без 3DS: успех только при <code>MOCK_SSL_PERMITTED=true</code>). Срок/CVV по умолчанию <code>1234</code>/<code>123</code>, <strong>пароль тестового ACS — <code>12345678</code></strong>, владелец карты — минимум два слова латиницей. Неверный срок/CVV, неверный пароль ACS или кнопка Fail — шлюзовой код <code>71015</code>. Оплата проходит только по тестовым картам: неизвестный валидный PAN отклоняется (<code>actionCode 5</code>), PAN с битой контрольной суммой Луна — <code>71015</code>. <strong>PAN не хранится</strong>: в заказе и журнале остаётся только маска <code>first6**last4</code> (F-10), платёжная форма не журналируется.</p><h2 id="Сценарии-x-mock-scenario-и-mockscenarios" tabindex="-1">Сценарии (X-Mock-Scenario и /mock/scenarios) <a class="header-anchor" href="#Сценарии-x-mock-scenario-и-mockscenarios" aria-label="Permalink to &quot;Сценарии (X-Mock-Scenario и /mock/scenarios)&quot;">​</a></h2><p>Заголовок <code>X-Mock-Scenario</code> (или поле <code>mock_scenario</code>, или правила <code>POST /mock/scenarios</code> с <code>target</code>): <code>fail</code> (системная ошибка, <code>errorCode 6</code>), <code>hang</code> (ответ не приходит), <code>webhook-drop</code>/<code>no-callback</code> (callback подавлен), <code>webhook-duplicate</code>/<code>callback-duplicate</code> (две копии уведомления), <code>latency:2s</code>, <code>http-500</code>, <code>http-504</code> (сетевой сбой до бизнес-логики, честные HTTP-коды), <code>X-Mock-Latency: 500ms</code>. Цели правил: <code>register</code>, <code>registerpreauth</code>, <code>deposit</code>, <code>reverse</code>, <code>refund</code>, <code>getorderstatus</code>, <code>getorderstatusextended</code>, <code>pay</code>, <code>3ds</code>, <code>*</code>.</p><p>Правила, история срабатываний и журнал <code>/admin/journal</code> принадлежат текущей песочнице (#52): другие песочницы их не видят и не очищают, <code>POST /mock/reset</code> действует только на целевую песочницу. Лимиты: до 200 правил на песочницу и до 8 KiB на правило (превышение — HTTP 400 с <code>code</code> <code>rule_cap_exceeded</code>/<code>rule_too_large</code>).</p><h2 id="Виртуальные-часы" tabindex="-1">Виртуальные часы <a class="header-anchor" href="#Виртуальные-часы" aria-label="Permalink to &quot;Виртуальные часы&quot;">​</a></h2><p><code>GET/POST /mock/time</code> (<code>{&quot;advance&quot;:&quot;+25m&quot;}</code>, <code>{&quot;offset&quot;:60000}</code>, <code>{&quot;reset&quot;:true}</code>) ускоряют истечение <code>sessionTimeoutSecs</code> (заказы переходят в <code>orderStatus=6</code> с callback <code>declinedByTimeout</code>) и ретраи callback — без реального ожидания.</p><h2 id="Песочницы-rfc-001" tabindex="-1">Песочницы (RFC-001) <a class="header-anchor" href="#Песочницы-rfc-001" aria-label="Permalink to &quot;Песочницы (RFC-001)&quot;">​</a></h2><p><code>MOCK_TENANCY=namespaces</code> (default): изоляция по заголовку <code>X-Mock-Sandbox</code> или <code>?sandbox=</code>. <code>MOCK_TENANCY=owned</code> (+ <code>MOCK_SANDBOX_TOKEN</code> закрывает default-стенд): <code>POST /sandboxes</code> выдаёт песочницу с <strong>своими</strong> кредами (<code>userName</code>, <code>password</code>, <code>callbackSecret</code> — секрет checksum) и <code>ownerToken</code> (показывается один раз); знание id без owner-token доступа не даёт. Свои эндпоинты — <code>/sandboxes/me</code>, <code>/sandboxes/me/reset</code>, <code>/sandboxes/me/reset-creds</code> (ownerToken сохраняется). Лимиты — <code>MOCK_SANDBOX_MAX</code>, <code>MOCK_SANDBOX_MAX_DOCUMENTS</code>, <code>MOCK_SANDBOX_CREATE_LIMIT</code>, TTL — <code>MOCK_SANDBOX_TTL_MS</code>, retention терминальных callback — <code>MOCK_SANDBOX_RETENTION_MS</code>.</p><h2 id="Переменные-окружения" tabindex="-1">Переменные окружения <a class="header-anchor" href="#Переменные-окружения" aria-label="Permalink to &quot;Переменные окружения&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Переменная</th><th>Default</th><th>Смысл</th></tr></thead><tbody><tr><td><code>MOCK_HOST</code> / <code>MOCK_PORT</code></td><td><code>0.0.0.0</code> / <code>3104</code></td><td>адрес стенда</td></tr><tr><td><code>MOCK_ALFA_USERNAME</code> / <code>ALFA_USERNAME</code></td><td><code>ALFAMOCKTEST</code></td><td>синтетический merchant-логин</td></tr><tr><td><code>MOCK_ALFA_PASSWORD</code> / <code>ALFA_PASSWORD</code></td><td><code>mockpass123</code></td><td>синтетический пароль</td></tr><tr><td><code>MOCK_ALFA_CALLBACK_SECRET</code> / <code>ALFA_CALLBACK_SECRET</code></td><td><code>mocksecret123</code></td><td>секрет симметричного checksum</td></tr><tr><td><code>MOCK_TWO_STAGE</code></td><td><code>true</code></td><td>двухстадийная схема (в бою включается банком)</td></tr><tr><td><code>MOCK_PARTIAL_REFUND</code></td><td><code>true</code></td><td>частичные возвраты («разрешённый контур»)</td></tr><tr><td><code>MOCK_SSL_PERMITTED</code></td><td><code>false</code></td><td>SSL-разрешение на операции без 3DS (карта <code>5555555555555599</code>)</td></tr><tr><td><code>MOCK_CALLBACK_CHECKSUM</code></td><td><code>true</code></td><td><code>false</code> — неподписанные callback (эмуляция оговорки PDF)</td></tr><tr><td><code>MOCK_SESSION_TIMEOUT_SECS</code></td><td><code>1200</code></td><td>дефолтный срок жизни заказа (переопределяется <code>sessionTimeoutSecs</code>); число секунд либо длительность (<code>&#39;20m&#39;</code>, <code>&#39;1h&#39;</code>), <code>0</code>/непарсимое — WARN и <code>1200</code></td></tr><tr><td><code>MOCK_ALFA_TERMINAL_ID</code></td><td><code>ALFA-MOCK-1</code></td><td><code>terminalId</code> в ответах статуса</td></tr><tr><td><code>MOCK_PUBLIC_BASE_URL</code></td><td><code>http://localhost:${MOCK_ALFA_HOST_PORT:-3104}</code></td><td>база для <code>formUrl</code></td></tr><tr><td><code>MOCK_DEFAULT_CALLBACK_URL</code></td><td>—</td><td>приёмник GET-callback по умолчанию (mock-расширение)</td></tr><tr><td><code>MOCK_CALLBACK_RETRY_MS</code> / <code>MOCK_CALLBACK_MAX_ATTEMPTS</code></td><td><code>10000</code> / <code>24</code></td><td>ретраи доставки — <strong>mock-конфиг</strong> (PDF параметры не задаёт); интервал — мс или длительность (<code>&#39;1h&#39;</code>), <code>0</code> — повтор без паузы; число попыток &lt; 1 — WARN и 1 попытка</td></tr><tr><td><code>MOCK_STATE_FILE</code></td><td>—</td><td>персистентность состояния между рестартами</td></tr><tr><td><code>MOCK_BLOCK_PRIVATE_WEBHOOKS</code></td><td><code>false</code> (hosted → <code>true</code>)</td><td>SSRF-защита исходящих callback</td></tr><tr><td><code>MOCK_VIRTUAL_CLOCK</code></td><td>—</td><td>стартовое смещение виртуальных часов</td></tr><tr><td><code>MOCK_ADMIN_TOKEN</code> / <code>MOCK_OPERATOR_TOKEN</code></td><td>—</td><td>токены <code>/admin*</code> и <code>/mock/*</code></td></tr><tr><td><code>MOCK_HOSTED</code></td><td><code>false</code></td><td><code>1</code> — fail-closed управляющей поверхности + SSRF-защита</td></tr><tr><td><code>MOCK_SANDBOX_TTL_MS</code> / <code>MOCK_SANDBOX_MAX</code></td><td><code>0</code> / <code>owned: 100</code></td><td>TTL песочницы и лимит их числа (RFC-001)</td></tr><tr><td><code>MOCK_SANDBOX_MAX_DOCUMENTS</code></td><td><code>5000</code> в <code>owned</code>, иначе <code>0</code> (выкл.)</td><td>квота документов песочницы: заказ + запись очереди callback; внутренний индекс <code>orderNumbers</code> документом не считается</td></tr><tr><td><code>MOCK_SANDBOX_CREATE_LIMIT</code></td><td><code>20</code> в <code>owned</code>, иначе <code>0</code> (выкл.)</td><td>лимит создания песочниц на IP в час</td></tr><tr><td><code>MOCK_SANDBOX_RETENTION_MS</code></td><td><code>0</code> (выкл.)</td><td>retention терминальных записей callback (история заказов не удаляется)</td></tr><tr><td><code>MOCK_SANDBOX_FILE</code></td><td><code>&lt;MOCK_STATE_FILE&gt;.sandboxes.json</code></td><td>база реестра песочниц: поштучные файлы в каталоге <code>&lt;база без .json&gt;.records/</code> (owner-токены — только хэши); в include не проброшена (долг «пяти мест», §2.6 AUDIT-PREP)</td></tr><tr><td><code>MOCK_SANDBOX_SWEEP_MS</code></td><td><code>60000</code></td><td>интервал воркера TTL/retention; воркер стартует при <code>TTL&gt;0</code>, квоте документов <code>&gt;0</code> или <code>RETENTION_MS&gt;0</code> (в дефолтном <code>namespaces</code> не стартует — просрочка удаляется «по касанию»); в include не проброшена (тот же долг)</td></tr><tr><td><code>MOCK_TENANCY</code>, <code>MOCK_SANDBOX_*</code></td><td>—</td><td>песочницы RFC-001 (см. выше)</td></tr></tbody></table><h2 id="Отличия-от-tbank-mock-и-yookassa-mock-не-drop-in" tabindex="-1">Отличия от <code>tbank-mock</code> и <code>yookassa-mock</code> — не drop-in <a class="header-anchor" href="#Отличия-от-tbank-mock-и-yookassa-mock-не-drop-in" aria-label="Permalink to &quot;Отличия от `tbank-mock` и `yookassa-mock` — не drop-in&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Т-Банк</th><th>ЮKassa</th><th>Альфа-Банк</th></tr></thead><tbody><tr><td>Транспорт</td><td>JSON <code>POST /v2/*</code></td><td>JSON <code>POST /v3/*</code> + Basic Auth</td><td>form-urlencoded <code>POST /payment/rest/*.do</code></td></tr><tr><td>Авторизация</td><td><code>TerminalKey</code> + подпись <code>Token</code> (sha256)</td><td><code>shopId:secretKey</code> Basic</td><td><code>userName</code>/<code>password</code> в каждом запросе</td></tr><tr><td>Идентификатор заказа</td><td><code>OrderId</code>/<code>PaymentId</code></td><td><code>payment_id</code>/<code>idempotence_key</code></td><td><code>orderNumber</code>/<code>orderId</code> (<code>mdOrder</code>)</td></tr><tr><td>Ответ регистрации</td><td><code>{Success, Status, PaymentId, FormUrl}</code></td><td><code>{id, status, confirmation}</code></td><td><code>{errorCode, errorMessage, orderId, formUrl}</code></td></tr><tr><td>Статусы</td><td>строковые <code>NEW/AUTHORIZED/CONFIRMED/…</code></td><td><code>pending/waiting_for_capture/succeeded/…</code></td><td>числовые <code>orderStatus 0…6</code></td></tr><tr><td>Callback</td><td>подписанный POST, ACK-тело <code>OK</code></td><td>POST JSON, ACK 200</td><td><strong>GET query + checksum HMAC-SHA256</strong>, ACK ровно 200</td></tr><tr><td>Идемпотентность</td><td><code>OrderId</code> уникален</td><td><code>Idempotence-Key</code></td><td><code>orderNumber</code> уникален, повтор — ошибка <code>errorCode 1</code></td></tr></tbody></table><p>Переносить tbank-маршруты, алгоритм подписи <code>Token</code> или юKassa-схемы на Альфу нельзя (<code>документации Альфа-Банк</code> — «не совместим с Т-Банком»).</p><h2 id="Границы-и-документированные-форки" tabindex="-1">Границы и документированные форки <a class="header-anchor" href="#Границы-и-документированные-форки" aria-label="Permalink to &quot;Границы и документированные форки&quot;">​</a></h2><p>Интерпретации мока там, где публичные материалы неполны или противоречивы (все зафиксированы также в <code>protocols/alfa-eacq.json</code> и отчёте PR #41):</p><ol><li><strong>Асимметричный checksum не реализован</strong> — официальная PDF-спецификация противоречива (описание: SHA-256; примеры Java/PHP: SHA-512), режим подтверждается банком. Только симметричный HMAC-SHA256; <code>sign_alias</code> не отправляется.</li><li><strong>Таблица <code>orderStatus 0…6</code></strong> взята из общей нумерации платформы RBS (снята в <code>документации Сбербанк Ecom</code> для того же семейства шлюзов; тестовый контур Альфы — <code>alfa.rbsuat.com</code>); в альфа-конспекте своя таблица не зафиксирована.</li><li><strong>Таблица <code>errorCode 0…6</code></strong> — классическая таблица RBS (в альфа-конспекте не снята). Маппинг мока: неизвестный заказ → 3; лимиты сумм и некорректные параметры → 5; недоступная двухстадийная схема → 5; системные и инфраструктурные сбои → 6 (с честными HTTP-кодами 404/405/413/500/504).</li><li><strong><code>declinedCardpresent</code></strong> перечислена в PDF без детальной семантики: мок отправляет её при отказе карточной авторизации (форма/ACS) со <code>status=0</code>. Источник истины — <code>getOrderStatusExtended.do</code> (<code>orderStatus=6</code>, <code>actionCode</code>).</li><li><strong><code>callbackCreationDate</code></strong> — epoch-миллисекунды (формат в конспекте не зафиксирован).</li><li><strong>Ретраи callback</strong> — собственная конфигурация мока (PDF не задаёт ни число попыток, ни интервал; копировать параметры Т-Банка/Сбера как «родные» нельзя).</li><li><strong>Дефолт <code>sessionTimeoutSecs</code> 1200 с (20 минут)</strong> — общая практика платформы RBS; лимит <code>orderNumber</code> ≤ 64 символов — интерпретация по той же практике. В альфа-конспекте оба значения не зафиксированы.</li><li><strong>Состав полей <code>getOrderStatusExtended.do</code></strong> (authorized/deposited/ refundedAmount + даты) — интерпретация по требованию конспекта «различать состояние, суммы и код шлюза»; точная схема RBS-ответа публично не снята.</li><li><strong>Неизвестный валидный PAN → <code>actionCode 5</code></strong> (общий отказ эмитента), <strong>операция без 3DS при выключенном SSL-разрешении → <code>actionCode 5</code></strong> — коды отказов для этих веток в конспекте не приведены.</li><li><strong>JSON-тело на <code>*.do</code> принимается</strong> (толерантность мока для отладки); контракт — form-urlencoded.</li><li><strong><code>/mock/verify-merchant</code> не реализован</strong>: экзаменатор ядра рассчитан на POST-JSON вебхуки (tbank/ferma), а callback Альфы — GET с query; алгоритм проверки checksum дан в гайде. Решение как в atol-mock/yookassa (#33).</li><li><strong>Вне области</strong>: привязки карт (<code>bindingId</code>), моделирование <code>orderBundle</code> (принимается, но не влияет на флоу), <code>paymentOrder.do</code> и альтернативные каналы, различия координат r-/i-логинов, лимит числа платёжных попыток на заказ (в платформе RBS — 3; в альфа-конспекте не зафиксирован).</li></ol><h2 id="Контракты-стенда-не-менялись" tabindex="-1">Контракты стенда не менялись <a class="header-anchor" href="#Контракты-стенда-не-менялись" aria-label="Permalink to &quot;Контракты стенда не менялись&quot;">​</a></h2><p>Ядро (<code>packages/core</code>) расширено <strong>аддитивно</strong>: очередь доставки и <code>postJson</code> научились исходящему <code>GET</code> без тела (<code>request(entry).method</code>) — для callback Альфа-Банка; поведение POST-доставки tbank/kassa/yookassa/atol не изменилось (их selftest&#39;ы проходят без правок). Порты существующих сервисов, их API и переменные окружения не тронуты; alfa-mock занял следующий свободный порт <strong>3104</strong>.</p><p>Selftest: <code>npm run test:alfa</code> (входит в <code>npm test</code>); black-box прогон стенда — <code>npm run test:compose</code> (секция 6). Манифест протокола — <code>protocols/alfa-eacq.json</code> (проверяется <code>npm run check:drift</code>), спецификация — <code>docs/openapi/alfa-mock.openapi.json</code>.</p><h2 id="Байтовые-квоты-состояния-pd-02" tabindex="-1">Байтовые квоты состояния (PD-02) <a class="header-anchor" href="#Байтовые-квоты-состояния-pd-02" aria-label="Permalink to &quot;Байтовые квоты состояния (PD-02)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Env</th><th>Дефолт</th><th>Назначение</th></tr></thead><tbody><tr><td><code>MOCK_SANDBOX_MAX_STATE_BYTES</code></td><td>пусто: <code>8388608</code> (8 МиБ) при <code>maxDocuments &gt; 0</code>, иначе без лимита</td><td>байты JSON одной песочницы; <code>0</code> выключает</td></tr><tr><td><code>MOCK_SANDBOX_GLOBAL_MAX_STATE_BYTES</code></td><td><code>67108864</code> (64 МиБ)</td><td>сумма байт JSON всех песочниц рантайма, включая <code>default</code>; <code>0</code> выключает</td></tr></tbody></table><p>Значения задаются в целых байтах. Пусто сохраняет дефолты. Квота per-sandbox не ограничивает память контейнера; общий бюджет меньше <code>mem_limit: 128m</code>, но не равен RSS. Превышение глобального бюджета на записи или байтовых квот при импорте <code>/mock/state</code> → HTTP 400, <code>errorCode: 400</code>, <code>kind: &#39;bytes&#39;</code>, <code>code: sandbox_state_budget_exceeded</code> / <code>sandbox_state_quota_exceeded</code>, с откатом отклонённого состояния. Правила/история/журнал остаются volatile. Подробности и границы — <a href="./../../packages/core/README#байтовые-квоты-песочниц-pd-02-74">документация ядра</a>.</p>',47)])])}const k=d(a,[["render",r]]);export{m as __pageData,k as default};
